import json, collections

def load(run):
    rows = []
    for line in open(f"bench/results/2026-10-12/m1-ngram/replay/{run}/requests.jsonl"):
        r = json.loads(line)
        if r["fg_bg"] == "fg": rows.append(r)
    return rows

for run in ["off-greedy", "A-greedy"]:
    print("==", run)
    stats = collections.defaultdict(lambda: {"n":0,"pred_n":0,"pred_ms":0,"draft_n":0,"draft_acc":0})
    for r in load(run):
        k = (r["phase"], r["role"])
        s = stats[k]; s["n"]+=1; s["pred_n"]+=r["predicted_n"]; s["pred_ms"]+=r["predicted_ms"]; s["draft_n"]+=r.get("draft_n") or 0; s["draft_acc"]+=r.get("draft_n_accepted") or 0
    for k in sorted(stats):
        s = stats[k]
        nonlen_n = nonlen_ms = 0
        rows = [x for x in load(run) if (x["phase"],x["role"])==k]
        for x in rows:
            if x["finish_reason"] != "length": nonlen_n += x["predicted_n"]; nonlen_ms += x["predicted_ms"]
        acc = s["draft_acc"]/s["draft_n"] if s["draft_n"] else 0
        print(f"  {k}: all {s['pred_n']}/{s['pred_ms']/1000:.1f}s={s['pred_n']/(s['pred_ms']/1000):.1f} tok/s | no-length {nonlen_n}/{nonlen_ms/1000:.1f}s={nonlen_n/(nonlen_ms/1000):.1f} tok/s | draft={s['draft_n']} acc={s['draft_acc']} ({acc:.0%})")
