import json, collections

def load(run):
    d = {}
    for line in open(f"bench/results/2026-10-12/m1-ngram/replay/{run}/requests.jsonl"):
        r = json.loads(line)
        if r["fg_bg"] == "fg":
            d[(r["phase"], r["id"])] = r
    return d

off = load("off-greedy"); a = load("A-greedy")
for phase in ["single-agent", "single-mem", "dual-agent", "dual-mem"]:
    ids = [k for k in off if k[0] == phase]
    same = sum(1 for k in ids if off[k]["out_sha256"] == a[k]["out_sha256"])
    diffs = [(k[1], off[k]["predicted_n"], a[k]["predicted_n"], off[k]["finish_reason"], a[k]["finish_reason"]) for k in ids if off[k]["out_sha256"] != a[k]["out_sha256"]]
    print(f"phase {phase}: same_sha {same}/{len(ids)}")
    print(f"  sha-different (id, off_n, a_n, off_reason, a_reason):")
    for t in sorted(diffs):
        print("   ", t)
    print(f"  phase totals off pred_n={sum(v['predicted_n'] for v in off.values() if v['phase']==phase)} A pred_n={sum(v['predicted_n'] for v in a.values() if v['phase']==phase)}")
